SELECT p.gender, i.icustay_id, i.intime, i.outtime, i.los, p.dod, COUNT(DISTINCT pr.procedure_id) AS avg_procedures, percentile_cont(0.25) within GROUP (ORDER BY COUNT(DISTINCT pr.procedure_id)) AS q1_procedures, percentile_cont(0.75) within GROUP (ORDER BY COUNT(DISTINCT pr.procedure_id)) AS q3_procedures, AVG(i.los) AS avg_los, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_rate, SUM(CASE WHEN i.intime <= i.outtime - interval '30 days' THEN 1 ELSE 0 END) AS readmission_rate FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN procedures_icd pr ON p.subject_id = pr.subject_id AND i.stay_id = pr.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 73 AND i.intime <= i.outtime - interval '72 hours' AND pr.icd_code IN (SELECT icd_code FROM diagnoses_icd WHERE icd_version = '4') GROUP BY p.gender, i.icustay_id, i.intime, i.outtime, i.los, p.dod ORDER BY p.gender, i.icustay_id, i.intime, i.outtime, i.los, p.dod NULLS LAST;